{
  "concept": "The tangential component of gravity provides a restoring force that continually accelerates a pendulum toward equilibrium; for small angles, this force is directly proportional to displacement, resulting in simple harmonic motion.",
  "figureType": "diagram",
  "elements": [
    "beige horizontal support bar at the top",
    "dashed vertical equilibrium line dropping from the pivot",
    "solid string labeled 'L'",
    "gray spherical bob labeled 'm'",
    "arc denoting angle 'θ' at the pivot between the vertical and the string",
    "dashed circular arc labeled 's' showing the bob's path from equilibrium",
    "dark blue arrow labeled 'F_T' pointing from the bob along the string toward the pivot",
    "red arrow pointing straight down labeled 'w = mg'",
    "red arrow pointing radially outward along the string axis labeled '-mg cosθ'",
    "red arrow pointing tangentially back toward equilibrium labeled '-mg sinθ'",
    "arc denoting angle 'θ' between the downward weight vector and the radial component vector",
    "tilted coordinate axes at the upper right with '+y' parallel to the string and '+x' tangent to the arc"
  ],
  "interactions": [
    {
      "id": "pendulumAngle",
      "type": "slider",
      "label": "Pendulum angle (θ)",
      "range": [-60, 60, 1],
      "default": 30,
      "teaches": "The magnitudes of the force components depend directly on the displacement angle: the restoring force grows and the radial component shrinks as the pendulum swings wider."
    },
    {
      "id": "swingMotion",
      "type": "animation",
      "label": "Animate swing",
      "loop": true,
      "teaches": "During continuous oscillation, the tangential component dynamically changes direction, always acting as a restoring force pointing back to the center equilibrium."
    },
    {
      "id": "forceModel",
      "type": "toggle",
      "label": "Restoring force model",
      "options": ["Exact (-mg sinθ)", "Small-Angle (-mg θ)"],
      "default": "Exact (-mg sinθ)",
      "teaches": "For very small angles, the exact sine curve approximates a straight line, making the restoring force proportional to displacement — the strict requirement for simple harmonic motion."
    }
  ],
  "demo_steps": [
    {
      "title": "Resolving the weight",
      "narration": "Gravity (w = mg) pulls straight down, but only the tangential component (-mg sinθ) pulls the bob along its circular path. The radial component is balanced by the string's tension.",
      "state": {
        "pendulumAngle": 30,
        "forceModel": "Exact (-mg sinθ)"
      }
    },
    {
      "title": "Large displacements",
      "narration": "At a steeper angle, the restoring force is large, but because it depends on the sine of the angle rather than the angle itself, the restoring force is non-linear.",
      "state": {
        "pendulumAngle": 60,
        "forceModel": "Exact (-mg sinθ)"
      }
    },
    {
      "title": "Small-angle approximation",
      "narration": "For small angles (typically < 15°), sin(θ) ≈ θ. The restoring force becomes essentially linear with respect to the displacement, creating ideal Simple Harmonic Motion.",
      "state": {
        "pendulumAngle": 12,
        "forceModel": "Small-Angle (-mg θ)"
      }
    }
  ],
  "keyInsight": "A pendulum is driven by the tangential component of its weight, which strictly becomes a simple harmonic oscillator only when the swing is small enough that sin(θ) and θ are effectively identical.",
  "reconstructionNotes": "Maintain the specific vector colors: blue for tension (along the string), red for weight and its components. The coordinate axes must remain tilted, matching the instantaneous tangent (+x) and radial (+y) directions defined by the bob's current position. When 'forceModel' toggles to small-angle, update the tangential label to '-mg θ'. Ensure the angle arc at the pivot and between the weight vectors visually update to match the slider."
}

