// @FIGURE_CODE_BEGIN
var draw = SVG().addTo('#container').size('100%', '100%');
draw.viewbox(0, 0, 600, 520);

// Colors and Dimensions
var colBg = '#f4eedc'; // beige top bar
var colT  = '#1e5288'; // tension vector blue
var colW  = '#d13d3d'; // weight vectors red
var px = 300, py = 50; // Pivot coordinate
var L = 270;
var W_len = 130;

// Draw Static Background Geometry
draw.rect(600, 25).fill(colBg).move(0, 0);
draw.line(px, 25, px, py + L + 60).stroke({color: '#777', width: 2, dasharray: '6,6'});

// Arcs & Paths
var arcPivot = draw.path().fill('none').stroke({width: 1.5, color: '#444'});
var pathS = draw.path().fill('none').stroke({width: 2.5, color: '#333', dasharray: '6,4'});

// Main Physical Components
var stringLine = draw.line().stroke({color: '#333', width: 2});
var bob = draw.circle(40).fill(draw.gradient('radial', function(add) {
  add.stop(0, '#ffffff');
  add.stop(1, '#999999');
})).stroke({color: '#555', width: 1});

var arcBob = draw.path().fill('none').stroke({width: 1.5, color: '#444'});

// Vector Arrow Markers (userSpaceOnUse prevents scaling issues with stroke width)
var mRed = draw.marker(14, 10, function(add) {
  add.polygon('0,0 14,5 0,10').fill(colW);
}).ref(12, 5).attr('markerUnits', 'userSpaceOnUse').orient('auto-start-reverse');

var mBlue = draw.marker(14, 10, function(add) {
  add.polygon('0,0 14,5 0,10').fill(colT);
}).ref(12, 5).attr('markerUnits', 'userSpaceOnUse').orient('auto-start-reverse');

