// Helper for generating arc paths seamlessly between two angles
function getArcPath(x, y, r, a1_deg, a2_deg) {
    if (Math.abs(a1_deg - a2_deg) < 0.1) return `M ${x} ${y+r}`;
    var a1 = a1_deg * Math.PI / 180;
    var a2 = a2_deg * Math.PI / 180;
    var x1 = x + r * Math.sin(a1);
    var y1 = y + r * Math.cos(a1);
    var x2 = x + r * Math.sin(a2);
    var y2 = y + r * Math.cos(a2);
    var flag = Math.abs(a2_deg - a1_deg) > 180 ? 1 : 0;
    var sweep = a2_deg > a1_deg ? 0 : 1; 
    return `M ${x1} ${y1} A ${r} ${r} 0 ${flag} ${sweep} ${x2} ${y2}`;
}

var currentTheta = 30;

// Core visual solver
function updateFig(theta_deg, isSmallAngle) {
  var t_rad = theta_deg * Math.PI / 180;

  // Bob coordinate
  var bx = px + L * Math.sin(t_rad);
  var by = py + L * Math.cos(t_rad);

  stringLine.plot(px, py, bx, by);
  bob.center(bx, by);
  bobCenter.center(bx, by);

  // Plot Vectors (Tension, Weight, Radial)
  var ftLen = W_len * Math.cos(t_rad);
  var tx = bx - ftLen * Math.sin(t_rad);
  var ty = by - ftLen * Math.cos(t_rad);
  vecT.plot(bx, by, tx, ty);

  vecW.plot(bx, by, bx, by + W_len);

  var rx = bx + ftLen * Math.sin(t_rad);
  var ry = by + ftLen * Math.cos(t_rad);
  vecRad.plot(bx, by, rx, ry);

  // Dynamic Tangential model (Linear approximation vs Exact sine curve)
  var tanMag = isSmallAngle ? (W_len * t_rad) : (W_len * Math.sin(t_rad));
  var tanX = bx - tanMag * Math.cos(t_rad);
  var tanY = by + tanMag * Math.sin(t_rad);
  vecTan.plot(bx, by, tanX, tanY);

  // Smoothly vanish components when passing purely through equilibrium zero
  var isZero = Math.abs(theta_deg) < 1;
  var op = isZero ? 0 : 1;
  vecTan.attr('opacity', op); txtTan.attr('opacity', op);
  vecRad.attr('opacity', op); txtRad.attr('opacity', op);
  arcBob.attr('opacity', op); arcPivot.attr('opacity', op);
  pathS.attr('opacity', op); txtS.attr('opacity', op);
  txtThetaB.attr('opacity', op); txtThetaP.attr('opacity', op);

  // Plot Angle Arcs
  arcPivot.plot(getArcPath(px, py, 70, 0, theta_deg));
  pathS.plot(getArcPath(px, py, L, 0, theta_deg));
  arcBob.plot(getArcPath(bx, by, 50, 0, theta_deg));

  // Dynamic Reference Axes
  axesGroup.transform({rotate: -theta_deg, ox: 480, oy: 150});

  // Offset Labels Contextually (prevent overlaps)
  var mx = px + (L/2)*Math.sin(t_rad);
  var my = py + (L/2)*Math.cos(t_rad);
  txtL.center(mx - 20*Math.cos(t_rad), my + 20*Math.sin(t_rad));

  txtM.center(bx + 35, by + 10);
  txtW.center(bx, by + W_len + 18);

  var tmidX = bx - (ftLen/2) * Math.sin(t_rad);
  var tmidY = by - (ftLen/2) * Math.cos(t_rad);
  txtFT.center(tmidX - 25*Math.cos(t_rad), tmidY + 25*Math.sin(t_rad));
  txtFT_sub.center(tmidX - 25*Math.cos(t_rad) + 12, tmidY + 25*Math.sin(t_rad) + 6);

  txtRad.center(rx + 30*Math.sin(t_rad), ry + 30*Math.cos(t_rad));

  txtTan.text(isSmallAngle ? '−mg θ' : '−mg sin θ');
  var sign = theta_deg >= 0 ? 1 : -1;
  txtTan.center(tanX - 45*sign*Math.cos(t_rad), tanY + 45*sign*Math.sin(t_rad) + 10);

  var s_mid = (theta_deg / 2) * Math.PI / 180;
  txtS.center(px + (L + 20) * Math.sin(s_mid), py + (L + 20) * Math.cos(s_mid));

  // Guard arcs text from squashing on the vertical baseline during very narrow angles
  var th_off = 85 * Math.sin(s_mid);
  if (Math.abs(th_off) < 18) th_off = 18 * sign;
  txtThetaP.center(px + th_off, py + 85 * Math.cos(s_mid));

  var thB_off = 65 * Math.sin(s_mid);
  if (Math.abs(thB_off) < 18) thB_off = 18 * sign;
  txtThetaB.center(bx + thB_off, by + 65 * Math.cos(s_mid));
}

// Controller Interactivity Links
var angleInput = document.getElementById('pendulumAngleInput');
var forceInput = document.getElementById('forceModelInput');

angleInput.addEventListener('input', function() {
  if (isAnimating) toggleSwing(); // Allow immediate takeover
  var val = parseFloat(this.value);
  document.getElementById('pendulumAngleVal').value = val;
  currentTheta = val;
  updateFig(val, forceInput.value.indexOf('Small') !== -1);
});

forceInput.addEventListener('change', function() {
  updateFig(currentTheta, this.value.indexOf('Small') !== -1);
});

// Oscillation Animation Loop
var isAnimating = false;
var animTime = 0;
var maxTheta = 30;
var lastTime = 0;
var reqId;

window.toggleSwing = function() {
  isAnimating = !isAnimating;
  var btn = document.getElementById('swingMotionBtn');
  if (isAnimating) {
    btn.innerHTML = '⏸ Stop animation';
    btn.classList.add('active');
    maxTheta = parseFloat(angleInput.value);
    animTime = 0;
    lastTime = performance.now();
    reqId = requestAnimationFrame(animLoop);
  } else {
    btn.innerHTML = '▶ Animate swing';
    btn.classList.remove('active');
    cancelAnimationFrame(reqId);
    angleInput.value = Math.round(currentTheta);
    document.getElementById('pendulumAngleVal').value = Math.round(currentTheta);
  }
};

function animLoop(time) {
  if (!isAnimating) return;
  var dt = (time - lastTime) / 1000;
  if (dt > 0.1) dt = 0.1; // Limit dt drift if tab unfocused
  lastTime = time;

  animTime += dt;
  var omega = 2.5; 
  currentTheta = maxTheta * Math.cos(omega * animTime);

  angleInput.value = Math.round(currentTheta);
